using System.Data;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace SchoolApp;
public partial class MainWindow:Window
{
 bool admin;DataTable services=new();readonly StackPanel rows=new();readonly TextBox search=new(){Width=290,Margin=new Thickness(4),Padding=new Thickness(6)};readonly ComboBox discount=new(){Width=170,Margin=new Thickness(4)};readonly ComboBox sort=new(){Width=200,Margin=new Thickness(4)};readonly TextBlock count=new(){Margin=new Thickness(12)};readonly StackPanel actions=new(){Orientation=Orientation.Horizontal};readonly Button login;
 public MainWindow(){InitializeComponent();Ui.Setup(this,"Языковая школа — услуги");var root=new DockPanel{Margin=new Thickness(16)};Content=root;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);top.Children.Add(Ui.Header("Услуги языковой школы"));var controls=new WrapPanel();top.Children.Add(controls);controls.Children.Add(new TextBlock{Text="Поиск:",VerticalAlignment=VerticalAlignment.Center});controls.Children.Add(search);foreach(var x in new[]{"Все скидки","От 0 до 5%","От 5 до 15%","От 15 до 30%","От 30 до 70%","От 70 до 100%"})discount.Items.Add(x);discount.SelectedIndex=0;controls.Children.Add(discount);foreach(var x in new[]{"Цена ↑","Цена ↓"})sort.Items.Add(x);sort.SelectedIndex=0;controls.Children.Add(sort);login=Ui.Button("Администратор",Login);controls.Children.Add(login);top.Children.Add(actions);actions.Children.Add(Ui.Button("Добавить услугу",()=>Edit(0)));actions.Children.Add(Ui.Button("Ближайшие записи",()=>new UpcomingWindow{Owner=this}.Show()));actions.Visibility=Visibility.Collapsed;DockPanel.SetDock(count,Dock.Bottom);root.Children.Add(count);root.Children.Add(new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});search.TextChanged+=(_,_)=>Filter();discount.SelectionChanged+=(_,_)=>Filter();sort.SelectionChanged+=(_,_)=>Filter();Loaded+=(_,_)=>Ui.Guard(LoadData);}
 void LoadData(){services=Db.Query("SELECT * FROM Service");Filter();}
 void Login(){if(admin){admin=false;}else{var w=new Window{Owner=this,Width=380,Height=245,ResizeMode=ResizeMode.NoResize};Ui.Setup(w,"Вход администратора");var p=new StackPanel{Margin=new Thickness(12)};w.Content=p;p.Children.Add(Ui.Header("Код доступа"));var code=new PasswordBox{Margin=new Thickness(4)};p.Children.Add(code);p.Children.Add(Ui.Button("Войти",()=>{if(code.Password!="0000")throw new Exception("Неверный код доступа.");admin=true;w.DialogResult=true;}));w.ShowDialog();}actions.Visibility=admin?Visibility.Visible:Visibility.Collapsed;login.Content=admin?"Выйти":"Администратор";Filter();}
 void Filter(){rows.Children.Clear();var q=services.AsEnumerable().Where(r=>(r.Field<string>("Title")+" "+(r["Description"] as string??"")).Contains(search.Text.Trim(),StringComparison.CurrentCultureIgnoreCase));double[] bounds={0,.05,.15,.30,.70,1};if(discount.SelectedIndex>0){int i=discount.SelectedIndex-1;q=q.Where(r=>Convert.ToDouble(r["Discount"]==DBNull.Value?0:r["Discount"])>=bounds[i]&&Convert.ToDouble(r["Discount"]==DBNull.Value?0:r["Discount"])<bounds[i+1]);}q=sort.SelectedIndex==1?q.OrderByDescending(Price):q.OrderBy(Price);var list=q.ToList();count.Text=$"{list.Count} из {services.Rows.Count}";foreach(var r in list){int id=(int)r["ID"];double d=r["Discount"]==DBNull.Value?0:Convert.ToDouble(r["Discount"]);var line=new DockPanel{Margin=new Thickness(8)};line.Children.Add(new Image{Source=Ui.Picture(r["MainImagePath"].ToString()!),Width=150,Height=105,Stretch=Stretch.Uniform,Margin=new Thickness(0,0,16,0)});if(admin){var buttons=new StackPanel();DockPanel.SetDock(buttons,Dock.Right);line.Children.Add(buttons);buttons.Children.Add(Ui.Button("Изменить",()=>Edit(id)));buttons.Children.Add(Ui.Button("Записать",()=>new BookingWindow(id){Owner=this}.ShowDialog()));buttons.Children.Add(Ui.Button("Удалить",()=>{if(MessageBox.Show("Удалить услугу?","Подтверждение",MessageBoxButton.YesNo)==MessageBoxResult.Yes){Db.Delete(id);LoadData();}}));}var text=new StackPanel();line.Children.Add(text);text.Children.Add(new TextBlock{Text=r["Title"].ToString(),FontSize=18,TextWrapping=TextWrapping.Wrap});if(d>0)text.Children.Add(new TextBlock{Text=$"{Convert.ToDecimal(r["Cost"]):N2} ₽",TextDecorations=TextDecorations.Strikethrough});text.Children.Add(new TextBlock{Text=$"{Price(r):N2} ₽ за {Convert.ToInt32(r["DurationInSeconds"])/60.0:0.##} минут",FontSize=17});text.Children.Add(new TextBlock{Text=$"Скидка: {d:P0}"});rows.Children.Add(new Border{Child=line,Background=d>0?Ui.Green:Brushes.White,BorderBrush=Brushes.LightGray,BorderThickness=new Thickness(1),Margin=new Thickness(0,4,0,4)});}}
 static decimal Price(DataRow r)=>Convert.ToDecimal(r["Cost"])*(1-(r["Discount"]==DBNull.Value?0:Convert.ToDecimal(r["Discount"])));
 void Edit(int id){if(!admin)return;var w=new ServiceWindow(id){Owner=this};if(w.ShowDialog()==true)LoadData();}
}
